<?php require '../config.php';need_admin();$title='Admin dashboard';$q=trim($_GET['q']??'');$status=$_GET['status']??'';$where=[];$args=[];if($q){$where[]='(title LIKE ? OR author_name LIKE ? OR author_email LIKE ?)';$args=["%$q%","%$q%","%$q%"]; }if($status){$where[]='status=?';$args[]=$status;}$sql='SELECT * FROM features'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY updated_at DESC';$s=db()->prepare($sql);$s->execute($args);$items=$s->fetchAll();$db=db();$total=$db->query('SELECT COUNT(*) FROM features')->fetchColumn();$votes=$db->query('SELECT COALESCE(SUM(votes),0) FROM features')->fetchColumn();$comments=$db->query('SELECT COUNT(*) FROM comments')->fetchColumn();$pending=$db->query("SELECT COUNT(*) FROM features WHERE status='under_review'")->fetchColumn();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="stylesheet" href="../assets/style.css"></head><body class="adminbody"><header class="adminnav"><div class="wrap nav"><a class="brand" href="../index.php"><span class="mark">F</span> FeatureBoard Admin</a><nav class="links"><a href="../index.php">View board</a><a href="logout.php">Log out</a></nav></div></header><div class="admin-shell"><aside class="side"><a class="active" href="index.php">Overview</a><a href="index.php?status=under_review">Needs review</a><a href="index.php?status=planned">Planned</a><a href="index.php?status=in_progress">In progress</a><a href="index.php?status=shipped">Shipped</a></aside><main class="main"><div style="display:flex;justify-content:space-between;align-items:end;gap:15px"><div><div class="eyebrow">Operations</div><h1 style="font-family:'Space Grotesk';margin:8px 0">Feedback inbox</h1><p style="color:var(--muted)">Every submitted request, vote, and discussion in one place.</p></div></div><div class="metrics"><div class="metric"><b><?=$total?></b><span>feature requests</span></div><div class="metric"><b><?=$votes?></b><span>community votes</span></div><div class="metric"><b><?=$comments?></b><span>comments</span></div><div class="metric"><b><?=$pending?></b><span>awaiting review</span></div></div><form class="toolbar" method="get"><input class="input search" name="q" value="<?=e($q)?>" placeholder="Search title, name, email…"><select class="select" name="status" style="max-width:190px"><option value="">All statuses</option><?php foreach(['under_review','planned','in_progress','shipped','declined'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach;?></select><button class="btn">Filter</button></form><div class="tablewrap"><table class="table"><thead><tr><th>Request</th><th>Submitter</th><th>Votes</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><a href="view.php?id=<?=$x['id']?>"><b><?=e($x['title'])?></b></a><br><span style="color:var(--muted)"><?=e($x['category'])?></span></td><td><?=e($x['author_name'])?><br><span style="color:var(--muted)"><?=e($x['author_email'])?></span></td><td><?=$x['votes']?></td><td><span class="status <?=e($x['status'])?>"><?=e(ucwords(str_replace('_',' ',$x['status'])))?></span></td><td><?=date('M j, Y',strtotime($x['updated_at']))?></td></tr><?php endforeach;?></tbody></table></div></main></div></body></html>
